// Load content database and validate exchange data
const fs = require('fs');
const path = require('path');

// Load content database
const contentDb = JSON.parse(
  fs.readFileSync('/Users/oktayshakirov/Coding/crypto-wiki/n8n-automation/content-database.json', 'utf8')
);

const exchangeData = $input.first().json;

// Validate required fields
if (!exchangeData.name || !exchangeData.website) {
  throw new Error('Exchange name and website are required');
}

// Check for duplicates in existing exchanges
const slugName = exchangeData.name.toLowerCase().replace(/[^a-z0-9]/g, '-').replace(/-+/g, '-');
const existingExchanges = Object.keys(contentDb.exchanges).map(key => 
  contentDb.exchanges[key].slug.replace('/exchanges/', '')
);

if (existingExchanges.includes(slugName)) {
  throw new Error(`Exchange "${exchangeData.name}" already exists. Cannot create duplicate.`);
}

// Get next order number for exchanges
const nextOrder = contentDb.next_orders.exchanges + 1;

// Prepare data for next node
return [{
  json: {
    ...exchangeData,
    slug: slugName,
    order: nextOrder,
    currentDate: new Date().toISOString().split('T')[0],
    contentDb: contentDb
  }
}];

// Generate content with enhanced internal linking using content database
const data = $input.first().json;
const contentDb = data.contentDb;

// Function to add internal links to text using content database
function addInternalLinks(text) {
  let processedText = text;

  // Process crypto OGs
  Object.entries(contentDb.crypto_ogs).forEach(([term, info]) => {
    const regex = new RegExp(`\\b${term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`, 'gi');
    processedText = processedText.replace(regex, (match) => {
      return `[${info.title}](${info.slug})`;
    });
  });

  // Process posts (with bold formatting)
  Object.entries(contentDb.posts).forEach(([term, info]) => {
    const regex = new RegExp(`\\b${term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`, 'gi');
    processedText = processedText.replace(regex, (match) => {
      return `**[${info.title}](${info.slug})**`;
    });
  });

  // Process exchanges (only if mentioned contextually and not the current exchange)
  Object.entries(contentDb.exchanges).forEach(([term, info]) => {
    if (term.toLowerCase() !== data.name.toLowerCase()) {
      const regex = new RegExp(`\\b${term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`, 'gi');
      processedText = processedText.replace(regex, (match) => {
        return `**[${info.title}](${info.slug})**`;
      });
    }
  });

  return processedText;
}

// Generate content with template
const generateContent = (exchangeData) => {
  const description = exchangeData.description || `${exchangeData.name} is a cryptocurrency exchange offering trading and related services.`;
  const foundingInfo = exchangeData.foundingYear ? ` Founded in ${exchangeData.foundingYear}` : '';
  const founderInfo = exchangeData.founder ? ` by ${exchangeData.founder}` : '';

  let content = `## **${exchangeData.name}: ${exchangeData.tagline || 'A Comprehensive Cryptocurrency Exchange'}**

`;

  // Opening paragraph
  content += `${foundingInfo}${founderInfo}, **${exchangeData.name}** has established itself as a ${exchangeData.positioning || 'notable cryptocurrency exchange'} in the digital asset landscape. `;
  content += `${description} This article provides a comprehensive overview of ${exchangeData.name}'s features, security measures, and what users should know before getting started.

`;

  // Core Offerings
  content += `## **Core Offerings and Services**

${exchangeData.name} provides a range of cryptocurrency-related services:

`;
  content += `- **Trading Platform:**
`;
  content += `  - **Spot Trading:** Buy, sell, and trade a variety of cryptocurrencies including **[Bitcoin](/posts/what-is-bitcoin)** and **[Ethereum](/posts/what-is-ethereum)**, along with numerous **[Altcoins](/posts/what-are-altcoins)**.
`;

  if (exchangeData.features?.derivatives) {
    content += `  - **Derivatives Trading:** Advanced trading options including futures and options contracts.
`;
  }

  if (exchangeData.features?.margin) {
    content += `  - **Margin Trading:** Leverage trading capabilities for eligible users.
`;
  }

  if (exchangeData.features?.staking) {
    content += `- **[Crypto Staking](/posts/crypto-staking):** Earn rewards on supported [Proof-of-Stake](/posts/what-is-proof-of-stake) cryptocurrencies.
`;
  }

  if (exchangeData.features?.defi) {
    content += `- **[DeFi](/posts/what-is-defi) Integration:** Access to decentralized finance protocols and services.
`;
  }

  if (exchangeData.features?.nft) {
    content += `- **[NFT](/posts/are-nfts-dead) Marketplace:** Buy, sell, and trade non-fungible tokens.
`;
  }

  content += `
![${exchangeData.name} Platform Interface](/images/exchanges/${exchangeData.slug}.png)

`;

  // Security
  content += `## **Security Measures and User Protection**

${exchangeData.name} implements various security measures to protect user assets:

`;
  content += `- **Account Security:** Multi-factor authentication (2FA), secure login procedures, and account monitoring.
`;
  content += `- **Platform Security:** ${exchangeData.security?.measures || 'Industry-standard security protocols including cold storage for digital assets and encryption for sensitive data.'}
`;

  if (exchangeData.security?.insurance) {
    content += `- **Insurance Coverage:** ${exchangeData.security.insurance}
`;
  }

  content += `
_Note: While ${exchangeData.name} implements security measures, users should always follow best practices for securing their accounts. Learn more: **[How To Store Crypto](/posts/how-to-store-crypto)** and **[How to Avoid Crypto Scams](/posts/how-to-avoid-crypto-scams)**._

`;

  // User Experience
  content += `## **User Experience and Features**

${exchangeData.name} aims to provide a user-friendly experience:

`;
  content += `- **Interface:** ${exchangeData.interface || 'User-friendly interface designed for both beginners and experienced traders.'}
`;

  if (exchangeData.mobileApp) {
    content += `- **Mobile Applications:** Available for both iOS and Android devices.
`;
  }

  if (exchangeData.education) {
    content += `- **Educational Resources:** ${exchangeData.education}
`;
  }

  content += `- **Customer Support:** ${exchangeData.support || 'Customer support available through multiple channels.'}

`;

  // Regulatory
  content += `## **Regulatory Compliance and Licensing**

${exchangeData.name} operates under various regulatory frameworks:

`;
  content += `- **Licensing:** ${exchangeData.regulatory?.licenses || 'Operates in compliance with applicable regulations in its jurisdictions.'}
`;
  content += `- **KYC/AML:** ${exchangeData.regulatory?.kyc || 'Implements Know Your Customer and Anti-Money Laundering procedures as required by law.'}
`;

  if (exchangeData.regulatory?.restrictions) {
    content += `- **Geographic Restrictions:** ${exchangeData.regulatory.restrictions}
`;
  }

  content += `
`;

  // Fees
  content += `## **Fees and Pricing**

${exchangeData.name}'s fee structure includes:

`;
  content += `- **Trading Fees:** ${exchangeData.fees?.trading || 'Competitive maker/taker fee structure based on trading volume.'}
`;
  content += `- **Deposit Fees:** ${exchangeData.fees?.deposit || 'Vary by payment method and currency.'}
`;
  content += `- **Withdrawal Fees:** ${exchangeData.fees?.withdrawal || 'Depend on the cryptocurrency and network being used.'}

`;

  // Considerations
  content += `## **Points to Consider Before Using ${exchangeData.name}**

`;
  content += `- **Regulatory Compliance:** Verify that ${exchangeData.name} is available and compliant in your jurisdiction.
`;
  content += `- **Fee Structure:** Review the complete fee schedule to understand costs for your intended trading activities.
`;
  content += `- **Security Practices:** While ${exchangeData.name} implements security measures, consider using additional security practices for account protection.
`;
  content += `- **Custodial Risk:** Remember that holding assets on any centralized exchange involves counterparty risk.

`;

  // Conclusion
  content += `## **Conclusion**

`;
  content += `${exchangeData.name} ${exchangeData.conclusion || `offers a comprehensive platform for cryptocurrency trading and related services. With its range of features and focus on user experience, it serves both newcomers and experienced traders in the digital asset space. As with any cryptocurrency exchange, users should carefully review the platform's features, fees, and security measures to determine if it meets their specific needs and risk tolerance.`}
`;

  return addInternalLinks(content);
};

const content = generateContent(data);

return [{
  json: {
    ...data,
    content: content
  }
}];

const data = $input.first().json;
const contentDb = data.contentDb;

// Create frontmatter with all social media options
const socialFields = [
  'android', 'apple', 'bitcoin', 'facebook', 'twitter', 'instagram', 
  'youtube', 'linkedin', 'github', 'medium', 'bitbucket', 'reddit', 
  'vk', 'whatsapp', 'tiktok', 'telegram', 'website', 'email', 
  'phone', 'address', 'wallet', 'wikipedia'
];

let socialSection = '';
socialFields.forEach(field => {
  if (data.social?.[field]) {
    socialSection += `  ${field}: ${data.social[field]}\n`;
  }
});

// Ensure website is always included
if (!socialSection.includes('website:')) {
  socialSection += `  website: ${data.website}\n`;
}

const frontmatter = `---
title: "${data.name}"
image: "/images/exchanges/${data.slug}.png"
description: "${data.description || `${data.name} offers comprehensive cryptocurrency trading and related services.`}"
date: ${data.currentDate}
order: ${data.order}
authors: ["Crypto Wiki Team"]
social:
${socialSection}---

`;

const fullContent = frontmatter + data.content;

return [{
  json: {
    ...data,
    fullContent: fullContent,
    fileName: `${data.slug}.mdx`,
    filePath: `/Users/oktayshakirov/Coding/crypto-wiki/content/exchanges/${data.slug}.mdx`
  }
}];

const fs = require('fs');
const data = $input.first().json;
const contentDb = data.contentDb;

try {
  // Write the file
  fs.writeFileSync(data.filePath, data.fullContent, 'utf8');

  // Update content database with new exchange
  const newExchange = {
    slug: data.slug,
    title: data.name,
    order: data.order
  };

  // Add to exchanges in content database
  contentDb.exchanges[data.slug] = newExchange;
  contentDb.next_orders.exchanges = data.order;

  // Write updated content database back to file
  fs.writeFileSync(
    '/Users/oktayshakirov/Coding/crypto-wiki/n8n-automation/content-database.json', 
    JSON.stringify(contentDb, null, 2), 
    'utf8'
  );

  console.log(`Successfully created exchange post: ${data.fileName}`);
  console.log(`Updated content database with new exchange: ${data.name}`);

  return [{
    json: {
      success: true,
      message: `Exchange post "${data.name}" created successfully`,
      fileName: data.fileName,
      filePath: data.filePath,
      order: data.order,
      updatedDatabase: true
    }
  }];
} catch (error) {
  console.error('Error writing file:', error);
  throw new Error(`Failed to create file: ${error.message}`);
}
